// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(1000, "", ""); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value > 0 && _value <= 1000);
        uint256 supplyBefore = c.totalSupply();
        c.burn(_value);
        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter == supplyBefore - _value);
    }
}

